public class CopyAction : DockingAction {
	private Clipboard clipboard;

	public CopyAction(DataTypeManagerPlugin plugin) : base("Copy", plugin.getName())
    {
		clipboard = plugin.getClipboard();
		string group = "Edit";

		setPopupMenuData(new MenuData(new string[] { "Copy" }, group));
		setKeyBindingData(new KeyBindingData(KeyStroke.getKeyStroke(KeyEvent.VK_C,
			DockingUtils.CONTROL_KEY_MODIFIER_MASK), ActionMapLevel));
		setEnabled(true);
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		if (!(context is DataTypesActionContext)) {
			return false;
		}

		GTree gtree = (GTree) context.getContextObject();
		TreePath[] selectionPaths = gtree.getSelectionPaths();
		if (selectionPaths == null || selectionPaths.length == 0) {
			return false;
		}

		return !containsInvalidNodes(selectionPaths);
	}

	private bool containsInvalidNodes(TreePath[] selectionPaths) {
		foreach (TreePath path in selectionPaths) {
			GTreeNode node = (GTreeNode) path.getLastPathComponent();
			if (node is ArchiveRootNode) {
				return true;
			}
			else if (node is DataTypeStoreNode) {
				return true;
			}
			else if (node is CategoryNode) {
				CategoryNode categoryNode = (CategoryNode) node;
				return !categoryNode.isEnabled();
			}
		}
		return false;
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		GTree gTree = (GTree) context.getContextObject();

		// cut to clipboard
		TreePath[] paths = gTree.getSelectionPaths();
		List<GTreeNode> nodeList = createList(paths);
		setClipboardContents(gTree, clipboard, nodeList);
	}

	private List<GTreeNode> createList(TreePath[] paths) {
		List<GTreeNode> list = new List<GTreeNode>();
		if (paths != null) {
			foreach (TreePath element in paths) {
				GTreeNode node = (GTreeNode) element.getLastPathComponent();
				list.add(node);
			}
		}
		return list;
	}

	/**
	 * Set the clipboard contents with the list of tree nodes.
	 * @param gTree the tree fro which the cut operation was triggered
	 * @param clipboard clipboard in which to place our contents
	 * @param list list of nodes to place into the clipboard
	 */
	private void setClipboardContents(GTree gTree, Clipboard clipboard,
			List<GTreeNode> list) {
		GTreeTransferHandler dragNDropHandler = gTree.getDragNDropHandler();
		Transferable contents = new GTreeNodeTransferable(dragNDropHandler, list);

		clipboard.setContents(contents, new _Anon_ClipboardOwner_1());
	}

	internal class _Anon_ClipboardOwner_1 : ClipboardOwner
	{

			/* @Override */
			public void lostOwnership(Clipboard currentClipboard, Transferable transferable) {
				// we don't care
			}
		
	}

}
